tool_input.new_string:
// bug7043：汇总项 activeDistrict 为 ''（value 语义），直接当 code 会找不到 feature、裁剪失效。
// 归一化：raw 为空或未命中区级 feature 时，从 districts 按 value/code 取当前项 code，
// 街道 9 位 code 归一到前 6 位（区级 adcode）重试；仍无命中则清空裁剪（全市）。
const features = suzhouGeo.features || []
const matchFeature = (c) => {
  const s = c == null ? '' : String(c)
  if (!s) return null
  return features.find((f) => {
    const p = f.properties || {}
    return String(p.adcode) === s || String(p.name) === s
  }) || null
}
const raw = this.activeDistrict
let feature = matchFeature(raw)
if (!feature) {
  const rawStr = raw == null ? '' : String(raw)
  const hit = (this.districts || []).find((d) => String(d.value) === rawStr || String(d.code) === rawStr)
  const hitCode = hit && hit.code != null && hit.code !== '' ? String(hit.code) : rawStr
  const normalized = hitCode.length > 6 ? hitCode.slice(0, 6) : hitCode
  feature = matchFeature(normalized)
}
if (!feature || !feature.geometry) {
  dom.style.clipPath = ''
  return
}

